  <script>
    const display = document.getElementById('display');

    function appendValue(value) {
      if (display.value === '0' && /[0-9.]/.test(value)) display.value = value;
      else display.value += value;
    }

    function clearDisplay() { display.value = '0'; }

    function deleteLast() {
      display.value = display.value.length > 1 ? display.value.slice(0, -1) : '0';
    }

    function calculate() {
      try {
        const expression = display.value.replace(/%/g, '/100');
        const result = Function('"use strict"; return (' + expression + ')')();
        display.value = Number.isFinite(result) ? result : 'خطأ';
      } catch { display.value = 'خطأ'; }
    }

    function squareRoot() {
      try {
        const number = Number(display.value);
        if (Number.isNaN(number) || number < 0) {
          display.value = 'خطأ';
          return;
        }
        display.value = Math.sqrt(number);
      } catch {
        display.value = 'خطأ';
      }
    }

    async function convertCurrency() {
      const amount = Number(document.getElementById('currencyAmount').value);
      const from = document.getElementById('fromCurrency').value;
      const to = document.getElementById('toCurrency').value;
      const resultEl = document.getElementById('currencyResult');
      const rateEl = document.getElementById('rateInfo');

      if (!Number.isFinite(amount) || amount < 0) {
        resultEl.textContent = 'أدخل مبلغًا صحيحًا';
        rateEl.textContent = '';
        return;
      }

      if (from === to) {
        resultEl.textContent = `${formatNumber(amount)} ${from} = ${formatNumber(amount)} ${to}`;
        rateEl.textContent = 'سعر التحويل: 1';
        return;
      }

      resultEl.textContent = 'جاري جلب سعر الصرف...';
      rateEl.textContent = '';

      try {
        const response = await fetch(`https://api.frankfurter.app/latest?amount=${encodeURIComponent(amount)}&from=${encodeURIComponent(from)}&to=${encodeURIComponent(to)}`);
        if (!response.ok) throw new Error('تعذر جلب سعر الصرف');
        const data = await response.json();
        const converted = data.rates && data.rates[to];
        if (!Number.isFinite(converted)) throw new Error('العملة غير مدعومة');

        const rate = converted / amount;
        resultEl.textContent = `${formatNumber(amount)} ${from} = ${formatNumber(converted)} ${to}`;
        rateEl.textContent = `سعر التحويل: 1 ${from} = ${formatNumber(rate)} ${to} • المصدر: Frankfurter`;
      } catch (error) {
        resultEl.textContent = 'تعذر جلب سعر الصرف. تحقق من اتصال الإنترنت.';
        rateEl.textContent = '';
      }
    }

    function formatNumber(value) {
      return new Intl.NumberFormat('en-US', { maximumFractionDigits: 6 }).format(value);
    }

    // لوحة المفاتيح تخص الحاسبة الرئيسية فقط.
    // عندما يكون المؤشر داخل تحويل العملات، تبقى الأرقام داخل حقل المبلغ ولا تصل للحاسبة الرئيسية.
    document.addEventListener('keydown', (event) => {
      if (event.target.closest('.currency-box')) {
        if (event.target.id === 'currencyAmount' && event.key === 'Enter') {
          convertCurrency();
          event.preventDefault();
        }
        return;
      }

      const key = event.key;

      if (/^[0-9.]$/.test(key)) {
        appendValue(key);
        event.preventDefault();
        return;
      }

      if (['+', '-', '*', '/', '%'].includes(key)) {
        appendValue(key);
        event.preventDefault();
        return;
      }

      if (key === 'Enter' || key === '=') {
        calculate();
        event.preventDefault();
        return;
      }

      if (key === 'Backspace') {
        deleteLast();
        event.preventDefault();
        return;
      }

      if (key === 'Escape' || key.toLowerCase() === 'c') {
        clearDisplay();
        event.preventDefault();
        return;
      }

      if (key.toLowerCase() === 'r') {
        squareRoot();
        event.preventDefault();
      }
    });
  </script>
